import './engineering-atlas.mjs?v=0.7.0';
import {modules} from './engineering-content.mjs';

const page=document.getElementById('page-engineering');
page.dataset.engineeringDesign='seascape';
const paths={aero:'M3 8h17m-4-4c5-5 10 5 2 5M3 14h22m-7 4c5 5 10-5 2-5M4 20h8',hydro:'M2 8q5-6 11 0t11 0M2 15q5-6 11 0t11 0M2 22q5-6 11 0t11 0',structure:'M14 3 4 24h20ZM14 3v12M4 24l10-9 10 9M14 15v9',mooring:'M14 6v17M7 10H3c0 10 5 14 11 14s11-4 11-14h-4M10 7a4 4 0 1 0 8 0 4 4 0 1 0-8 0',control:'M14 11V1m0 10L3 22m11-11 11 11M12 14v11m4-11v11',home:'M3 13 14 3l11 10M6 11v15h7v-8h4v8h6V11',model:'M14 2v9M14 11 3 21m11-10 11 10M14 11v15M1 21h6v6H1Zm10 0h6v6h-6Zm10 0h6v6h-6ZM11 1h6v6h-6Z',configure:'M14 3v4m0 14v4M3 14h4m14 0h4M7 7l3 3m8 8 3 3m0-14-3 3M7 21l3-3M21 14a7 7 0 1 1-14 0 7 7 0 1 1 14 0',analysis:'M3 4v22h23V4ZM7 20l5-8 5 4 5-8',records:'M3 4h22v21H3ZM7 9h13M7 14h6M7 20l4-3 4 3 6-7',reports:'M6 2h12l7 7v18H6ZM18 2v7h7M10 14h10M10 19h10M10 23h6'};
const icon=(id,cls='')=>`<svg class="ocean-icon ${cls}" viewBox="0 0 28 28" aria-hidden="true"><path d="${paths[id]||paths.hydro}"/></svg>`;
const hero=page.querySelector('.atlas-hero'),tabs=page.querySelector('.atlas-tabs'),copy=page.querySelector('.atlas-copy'),coupling=page.querySelector('.atlas-coupling');
hero.classList.add('ocean-stage');
hero.replaceChildren();
hero.insertAdjacentHTML('afterbegin',`<div class="ocean-scene" role="img" aria-label="海上风机与半潜式平台的海面及水下系泊原理示意"></div><svg class="ocean-forces" viewBox="0 0 1586 992" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="sea-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 10 5 0 10 2 5Z" fill="#d6ffff"/></marker><filter id="sea-glow"><feGaussianBlur stdDeviation="2"/></filter></defs><g data-load="aero"><path d="M280 126Q350 158 422 148M275 148Q350 185 411 172M270 172Q338 205 393 197"/></g><g data-load="hydro"><path d="M190 385Q235 354 280 379T390 390M188 405Q235 380 280 401T383 414"/></g><g data-load="structure"><path d="M696 442V386M708 443Q747 428 727 412"/></g><g data-load="mooring"><path d="M800 711Q741 685 775 604M809 738Q763 710 784 645"/></g><g data-load="control"><path d="M608 138Q632 165 605 198"/></g></svg><button class="sea-callout sea-wind" data-topic="aero">风载荷</button><button class="sea-callout sea-wave" data-topic="hydro">波浪载荷</button><button class="sea-callout sea-motion" data-topic="structure">平台运动</button><button class="sea-callout sea-mooring" data-topic="mooring">系泊恢复力</button><div class="sea-depth-scales" aria-hidden="true"><span>0 m</span><span>−50 m</span><span>−100 m</span><span>−200 m</span><span>−500 m</span></div><small class="sea-scene-note">原理示意 · 非仿真结果</small><button class="sea-explore" data-jump="principle-deep">⌄ <span>向下探索原理</span></button>`);
hero.append(tabs,copy,coupling);
hero.insertAdjacentHTML('afterbegin',`<svg class="sea-contours" viewBox="0 0 420 220" aria-hidden="true">${Array.from({length:13},(_,i)=>`<path d="M-30 ${30+i*9}C85 ${-36+i*11} 112 ${153+i*5} 235 ${140+i*6}S350 ${204+i*4} 440 ${178+i*5}"/>`).join('')}</svg>`);
tabs.querySelectorAll('button').forEach(b=>{const m=modules.find(m=>m.id===b.dataset.topic),code={aero:'AeroDyn',hydro:'HydroDyn',structure:'ElastoDyn',mooring:'MoorDyn',control:'ServoDyn'}[m.id];b.innerHTML=`${icon(m.id)}<span class="sea-tab-label">${m.name}<small>${code}</small></span>`;});
const wavePath='M64 2H650Q670 2 680 23L704 72Q708 83 707 99L698 467Q696 490 674 508Q659 520 637 522H323Q284 522 250 509L180 488Q158 482 130 482H70Q32 482 16 451Q4 428 9 401L25 305Q37 232 24 161L7 72Q0 44 18 22Q35 2 64 2Z';
copy.innerHTML=`<svg class="sea-panel-surface" viewBox="0 0 710 525" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="sea-panel-fill" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#0a5374" stop-opacity=".72"/><stop offset=".5" stop-color="#03253d" stop-opacity=".82"/><stop offset="1" stop-color="#104f78" stop-opacity=".70"/></linearGradient><linearGradient id="sea-panel-edge" x1="0" y1="0" x2="1" y2=".8"><stop stop-color="#c7fdff" stop-opacity=".96"/><stop offset=".48" stop-color="#75d9ff" stop-opacity=".6"/><stop offset="1" stop-color="#afb7ff" stop-opacity=".95"/></linearGradient></defs><path d="${wavePath}" fill="url(#sea-panel-fill)" stroke="url(#sea-panel-edge)" stroke-width="1.3"/><path d="${wavePath}" fill="none" stroke="#c2edff" stroke-opacity=".18" stroke-width="6"/></svg><div class="sea-panel-inner"><div class="sea-card-eyebrow">Ⅰ　工程原理 <span>≋　原理示意</span></div><span id="atlas-label" class="visually-hidden"></span><div class="sea-title"><h2 id="atlas-title"></h2><span id="atlas-code"></span></div><p id="atlas-description" class="sea-description"></p><div class="sea-columns"><section class="sea-input"><h3>输入</h3><div class="sea-column-body"><strong id="atlas-input"></strong><p id="atlas-input-note"></p><strong class="sea-secondary-input">耦合信息</strong><p>平台运动与其他模块交换的状态量。</p></div></section><section class="sea-process"><h3>作用机理</h3><div class="sea-column-body">${icon('hydro','sea-process-icon')}<strong id="atlas-effect"></strong><p id="atlas-effect-note"></p></div></section><section class="sea-output"><h3>输出</h3><div id="sea-output-list" class="sea-column-body"></div><span id="atlas-watch" class="visually-hidden"></span><span id="atlas-watch-note" class="visually-hidden"></span></section></div><div class="atlas-actions"><a class="atlas-primary" id="atlas-source" target="_blank" rel="noopener">▣　官方文档 <span>→</span></a><button class="atlas-secondary" data-page="configure">⚙　配置工况 <span>→</span></button></div></div>`;
coupling.querySelector('.atlas-section-caption').innerHTML='<h2 id="coupling-title">OpenFAST <span>模块耦合关系</span></h2>';
coupling.querySelector('.coupling-note').textContent='模块通过 OpenFAST 交换载荷、运动与控制量；连线表示耦合关联。';
coupling.querySelectorAll('.coupling-node').forEach(b=>{b.insertAdjacentHTML('afterbegin',`<span class="sea-node-icon">${icon(b.dataset.topic)}</span>`);});
coupling.querySelector('.coupling-core').insertAdjacentHTML('afterbegin','<span class="sea-node-icon sea-core-symbol">◉</span>');
coupling.remove();
const sidebar=document.querySelector('.sidebar');
sidebar.insertAdjacentHTML('afterbegin','<svg class="ocean-sidebar-surface" viewBox="0 0 210 1000" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="sea-nav-fill"><stop stop-color="#084263" stop-opacity=".61"/><stop offset="1" stop-color="#0a5476" stop-opacity=".35"/></linearGradient></defs><path d="M0 0H171Q209 95 179 239Q139 401 153 534Q167 675 113 797Q112 857 172 919L210 1000H0Z" fill="url(#sea-nav-fill)" stroke="#9cdeff" stroke-opacity=".62"/><path d="M164 0Q202 95 172 239Q132 401 146 534Q160 675 106 797" fill="none" stroke="#64d9f0" stroke-opacity=".16" stroke-width="6"/></svg><div class="sea-nav-caption">潮境 · 深海视窗<small>TIDEFLOW<br>OCEAN EXPLORATION</small></div>');
sidebar.querySelectorAll('.nav').forEach(b=>b.insertAdjacentHTML('afterbegin',icon(b.dataset.page)));
const names={Wave1Elev:'波浪表面高程序列',PtfmPitch:'平台纵摇运动',PtfmSurge:'平台纵荡运动',RotSpeed:'转子转速',GenPwr:'发电机功率',TwrBsMyt:'塔底弯矩'};
function sync(){const id=page.dataset.topic||'hydro',m=modules.find(m=>m.id===id);document.getElementById('atlas-description').textContent=m.text;document.getElementById('sea-output-list').innerHTML=m.watch.split(' / ').map((channel,i)=>`<div class="sea-channel"><span>${icon(i===0?'hydro':i===1?'configure':'aero')}</span><div><b>${channel}</b><small>${names[channel]||'响应时序'}</small></div></div>`).join('');page.querySelector('.sea-process-icon').innerHTML=`<path d="${paths[id]}"/>`;}
new MutationObserver(sync).observe(page,{attributes:true,attributeFilter:['data-topic']});
tabs.querySelector('[data-topic="hydro"]').click();sync();
